  1	package com.pousada.service;
  2	
  3	import com.pousada.model.Reservation;
  4	import com.pousada.model.ReservationStatus;
  5	import com.pousada.model.Room;
  6	import com.pousada.model.RatePlan;
  7	import com.pousada.repository.ReservationRepository;
  8	import com.pousada.repository.RoomRepository;
  9	
 10	import java.math.BigDecimal;
 11	import java.time.LocalDate;
 12	import java.time.YearMonth;
 13	import java.time.format.DateTimeFormatter;
 14	import java.util.*;
 15	import java.util.stream.Collectors;
 16	
 17	public class ReportService {
 18	    private final ReservationRepository reservationRepository;
 19	    private final RoomRepository roomRepository;
 20	
 21	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
 22	        this.reservationRepository = reservationRepository;
 23	        this.roomRepository = roomRepository;
 24	    }
 25	
 26	    public String generateOccupancyReport(LocalDate date) {
 27	        StringBuilder csv = new StringBuilder();
 28	        csv.append("Pousada Maré Alta,occupancy,").append(date.format(DateTimeFormatter.ofPattern("yyyy-MM-dd"))).append("\n");
 29	        csv.append("room,type,reservation,check_in,check_out\n");
 30	
 31	        int occupiedRooms = 0;
 32	
 33	        var sortedRooms = roomRepository.findAll().stream()
 34	            .sorted(Comparator.comparingInt(Room::getNumber))
 35	            .collect(Collectors.toList());
 36	
 37	        for (Room room : sortedRooms) {
 38	            var reservations = reservationRepository.findAll().stream()
 39	                .filter(r -> r.getRoomNumber() == room.getNumber())
 40	                .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
 41	                .filter(r -> isReservationOnDate(r, date))
 42	                .collect(Collectors.toList());
 43	
 44	            if (!reservations.isEmpty()) {
 45	                for (Reservation r : reservations) {
 46	                    csv.append(room.getNumber()).append(",")
 47	                        .append(room.getType()).append(",")
 48	                        .append(r.getId()).append(",")
 49	                        .append(r.getCheckIn().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"))).append(",")
 50	                        .append(r.getCheckOut().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"))).append("\n");
 51	                    occupiedRooms++;
 52	                }
 53	            }
 54	        }
 55	
 56	        csv.append("total,").append(occupiedRooms).append("/").append(roomRepository.findAll().size()).append("\n");
 57	
 58	        return csv.toString();
 59	    }
 60	
 61	    public String generateRevenueReport(YearMonth month) {
 62	        StringBuilder csv = new StringBuilder();
 63	        csv.append("Pousada Maré Alta,revenue,").append(month.format(DateTimeFormatter.ofPattern("yyyy-MM"))).append("\n");
 64	        csv.append("reservation,room,check_in,check_out,status,amount\n");
 65	
 66	        BigDecimal totalAmount = BigDecimal.ZERO;
 67	
 68	        var reservations = reservationRepository.findByMonth(month.getYear(), month.getMonthValue()).stream()
 69	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED || r.getStatus() == ReservationStatus.CANCELLED)
 70	            .sorted(Comparator.comparing(Reservation::getCheckIn).thenComparingLong(Reservation::getId))
 71	            .collect(Collectors.toList());
 72	
 73	        for (Reservation r : reservations) {
 74	            if (r.getStatus() != ReservationStatus.PENDING && r.getStatus() != ReservationStatus.CANCELLED) {
 75	                csv.append(r.getId()).append(",")
 76	                    .append(r.getRoomNumber()).append(",")
 77	                    .append(r.getCheckIn().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"))).append(",")
 78	                    .append(r.getCheckOut().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"))).append(",")
 79	                    .append(r.getStatus()).append(",")
 80	                    .append(formatAmount(r.getAmountPaid().subtract(r.getRefund() != null ? r.getRefund() : BigDecimal.ZERO))).append("\n");
 81	
 82	                totalAmount = totalAmount.add(r.getAmountPaid().subtract(r.getRefund() != null ? r.getRefund() : BigDecimal.ZERO));
 83	            } else if (r.getStatus() == ReservationStatus.CANCELLED && r.getRatePlan() == RatePlan.NON_REFUNDABLE) {
 84	                // Non-refundable cancelled reservations still count
 85	                csv.append(r.getId()).append(",")
 86	                    .append(r.getRoomNumber()).append(",")
 87	                    .append(r.getCheckIn().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"))).append(",")
 88	                    .append(r.getCheckOut().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"))).append(",")
 89	                    .append(r.getStatus()).append(",")
 90	                    .append(formatAmount(r.getAmountPaid())).append("\n");
 91	
 92	                totalAmount = totalAmount.add(r.getAmountPaid());
 93	            }
 94	        }
 95	
 96	        csv.append("total,,,,").append(formatAmount(totalAmount)).append("\n");
 97	
 98	        return csv.toString();
 99	    }
100	
101	    public String generateTourismTaxReport(YearMonth month) {
102	        StringBuilder csv = new StringBuilder();
103	        csv.append("Pousada Maré Alta,tourism-tax,").append(month.format(DateTimeFormatter.ofPattern("yyyy-MM"))).append("\n");
104	        csv.append("reservation,room,check_in,check_out,guests,nights,tax\n");
105	
106	        BigDecimal totalTax = BigDecimal.ZERO;
107	        final BigDecimal TAX_PER_GUEST_PER_NIGHT = new BigDecimal("4.50");
108	
109	        var reservations = reservationRepository.findByMonth(month.getYear(), month.getMonthValue()).stream()
110	            .filter(r -> r.getStatus() == ReservationStatus.CONFIRMED || r.getStatus() == ReservationStatus.CHECKED_IN || r.getStatus() == ReservationStatus.CHECKED_OUT)
111	            .sorted(Comparator.comparing(Reservation::getCheckIn).thenComparingLong(Reservation::getId))
112	            .collect(Collectors.toList());
113	
114	        for (Reservation r : reservations) {
115	            BigDecimal tax = TAX_PER_GUEST_PER_NIGHT
116	                .multiply(BigDecimal.valueOf(r.getGuests()))
117	                .multiply(BigDecimal.valueOf(r.getNights()));
118	
119	            csv.append(r.getId()).append(",")
120	                .append(r.getRoomNumber()).append(",")
121	                .append(r.getCheckIn().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"))).append(",")
122	                .append(r.getCheckOut().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"))).append(",")
123	                .append(r.getGuests()).append(",")
124	                .append(r.getNights()).append(",")
125	                .append(formatAmount(tax)).append("\n");
126	
127	            totalTax = totalTax.add(tax);
128	        }
129	
130	        csv.append("total,,,,,").append(formatAmount(totalTax)).append("\n");
131	
132	        return csv.toString();
133	    }
134	
135	    public String generateRatePlansReport(YearMonth month) {
136	        StringBuilder csv = new StringBuilder();
137	        csv.append("Pousada Maré Alta,rate-plans,").append(month.format(DateTimeFormatter.ofPattern("yyyy-MM"))).append("\n");
138	        csv.append("rate_plan,reservations,amount\n");
139	
140	        var allReservations = reservationRepository.findByMonth(month.getYear(), month.getMonthValue());
141	
142	        Map<RatePlan, BigDecimal> amountByPlan = new HashMap<>();
143	        Map<RatePlan, Integer> countByPlan = new HashMap<>();
144	
145	        for (RatePlan plan : RatePlan.values()) {
146	            amountByPlan.put(plan, BigDecimal.ZERO);
147	            countByPlan.put(plan, 0);
148	        }
149	
150	        for (Reservation r : allReservations) {
151	            // Include paid reservations and cancelled non-refundable
152	            if (r.getStatus() != ReservationStatus.PENDING && r.getStatus() != ReservationStatus.CANCELLED) {
153	                BigDecimal amount = r.getAmountPaid().subtract(r.getRefund() != null ? r.getRefund() : BigDecimal.ZERO);
154	                amountByPlan.put(r.getRatePlan(), amountByPlan.get(r.getRatePlan()).add(amount));
155	                countByPlan.put(r.getRatePlan(), countByPlan.get(r.getRatePlan()) + 1);
156	            } else if (r.getStatus() == ReservationStatus.CANCELLED && r.getRatePlan() == RatePlan.NON_REFUNDABLE) {
157	                // Non-refundable cancelled reservations still count
158	                amountByPlan.put(r.getRatePlan(), amountByPlan.get(r.getRatePlan()).add(r.getAmountPaid()));
159	                countByPlan.put(r.getRatePlan(), countByPlan.get(r.getRatePlan()) + 1);
160	            }
161	        }
162	
163	        BigDecimal totalAmount = BigDecimal.ZERO;
164	        int totalCount = 0;
165	
166	        for (RatePlan plan : RatePlan.values()) {
167	            csv.append(plan).append(",")
168	                .append(countByPlan.get(plan)).append(",")
169	                .append(formatAmount(amountByPlan.get(plan))).append("\n");
170	
171	            totalAmount = totalAmount.add(amountByPlan.get(plan));
172	            totalCount += countByPlan.get(plan);
173	        }
174	
175	        csv.append("total,").append(totalCount).append(",").append(formatAmount(totalAmount)).append("\n");
176	
177	        return csv.toString();
178	    }
179	
180	    private boolean isReservationOnDate(Reservation reservation, LocalDate date) {
181	        return !reservation.getCheckIn().isAfter(date) && date.isBefore(reservation.getCheckOut());
182	    }
183	
184	    private String formatAmount(BigDecimal amount) {
185	        return String.format("%.2f", amount);
186	    }
187	}

