  1	package com.pousada;
  2	
  3	import io.javalin.Javalin;
  4	import com.fasterxml.jackson.databind.ObjectMapper;
  5	import com.fasterxml.jackson.databind.SerializationFeature;
  6	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  7	
  8	import com.pousada.dto.*;
  9	import com.pousada.model.*;
 10	import com.pousada.repository.*;
 11	import com.pousada.service.*;
 12	
 13	import java.math.BigDecimal;
 14	import java.time.LocalDate;
 15	import java.time.YearMonth;
 16	import java.time.format.DateTimeFormatter;
 17	
 18	public class Application {
 19	    public static void main(String[] args) {
 20	        // Repositories
 21	        RoomRepository roomRepository = new RoomRepository();
 22	        ReservationRepository reservationRepository = new ReservationRepository();
 23	        MessageRepository messageRepository = new MessageRepository();
 24	
 25	        // Services
 26	        ReservationService reservationService = new ReservationService(reservationRepository, roomRepository);
 27	        MessageService messageService = new MessageService(messageRepository);
 28	        DocumentService documentService = new DocumentService(roomRepository);
 29	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 30	
 31	        // Configure Jackson for LocalDate handling
 32	        ObjectMapper mapper = new ObjectMapper();
 33	        mapper.registerModule(new JavaTimeModule());
 34	        mapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 35	
 36	        // Create Javalin app
 37	        String port = System.getenv("PORT");
 38	        int portNumber = port != null ? Integer.parseInt(port) : 7070;
 39	
 40	        Javalin app = Javalin.create()
 41	            .start(portNumber);
 42	
 43	        // GET /rooms
 44	        app.get("/rooms", ctx -> {
 45	            var rooms = roomRepository.findAll();
 46	            var roomDTOs = rooms.stream()
 47	                .map(RoomDTO::from)
 48	                .toList();
 49	            ctx.json(roomDTOs);
 50	        });
 51	
 52	        // POST /reservations
 53	        app.post("/reservations", ctx -> {
 54	            try {
 55	                var body = ctx.bodyAsClass(java.util.Map.class);
 56	
 57	                // Validate
 58	                if (!body.containsKey("roomNumber") || !body.containsKey("guestName") ||
 59	                    !body.containsKey("guestEmail") || !body.containsKey("guestCpf") ||
 60	                    !body.containsKey("checkIn") || !body.containsKey("checkOut") ||
 61	                    !body.containsKey("guests") || !body.containsKey("ratePlan")) {
 62	                    ctx.status(400).json(new ErrorDTO("INVALID_REQUEST", "Missing required fields"));
 63	                    return;
 64	                }
 65	
 66	                int roomNumber = ((Number) body.get("roomNumber")).intValue();
 67	                String guestName = (String) body.get("guestName");
 68	                String guestEmail = (String) body.get("guestEmail");
 69	                String guestCpf = (String) body.get("guestCpf");
 70	                String checkInStr = (String) body.get("checkIn");
 71	                String checkOutStr = (String) body.get("checkOut");
 72	                int guests = ((Number) body.get("guests")).intValue();
 73	                String ratePlanStr = (String) body.get("ratePlan");
 74	
 75	                LocalDate checkIn = LocalDate.parse(checkInStr, DateTimeFormatter.ISO_LOCAL_DATE);
 76	                LocalDate checkOut = LocalDate.parse(checkOutStr, DateTimeFormatter.ISO_LOCAL_DATE);
 77	                RatePlan ratePlan = RatePlan.valueOf(ratePlanStr);
 78	
 79	                Reservation reservation = reservationService.createReservation(
 80	                    roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan
 81	                );
 82	
 83	                ctx.status(201).json(ReservationDTO.from(reservation));
 84	            } catch (RuntimeException e) {
 85	                handleError(ctx, e);
 86	            }
 87	        });
 88	
 89	        // GET /reservations/{id}
 90	        app.get("/reservations/{id}", ctx -> {
 91	            try {
 92	                long id = Long.parseLong(ctx.pathParam("id"));
 93	                Reservation reservation = reservationService.getReservation(id);
 94	                ctx.json(ReservationDTO.from(reservation));
 95	            } catch (RuntimeException e) {
 96	                handleError(ctx, e);
 97	            }
 98	        });
 99	
100	        // POST /reservations/{id}/confirmation
101	        app.post("/reservations/{id}/confirmation", ctx -> {
102	            try {
103	                long id = Long.parseLong(ctx.pathParam("id"));
104	                Reservation reservation = reservationService.confirmReservation(id);
105	
106	                // Send confirmation email
107	                String comprovante = documentService.generateComprovante(reservation);
108	                messageService.sendConfirmationEmail(reservation, comprovante);
109	
110	                ctx.json(ReservationDTO.from(reservation));
111	            } catch (RuntimeException e) {
112	                handleError(ctx, e);
113	            }
114	        });
115	
116	        // POST /reservations/{id}/cancellation
117	        app.post("/reservations/{id}/cancellation", ctx -> {
118	            try {
119	                long id = Long.parseLong(ctx.pathParam("id"));
120	                Reservation reservation = reservationService.cancelReservation(id);
121	                ctx.json(ReservationDTO.from(reservation));
122	            } catch (RuntimeException e) {
123	                handleError(ctx, e);
124	            }
125	        });
126	
127	        // POST /reservations/{id}/check-in
128	        app.post("/reservations/{id}/check-in", ctx -> {
129	            try {
130	                long id = Long.parseLong(ctx.pathParam("id"));
131	                Reservation reservation = reservationService.checkIn(id);
132	                ctx.json(ReservationDTO.from(reservation));
133	            } catch (RuntimeException e) {
134	                handleError(ctx, e);
135	            }
136	        });
137	
138	        // POST /reservations/{id}/check-out
139	        app.post("/reservations/{id}/check-out", ctx -> {
140	            try {
141	                long id = Long.parseLong(ctx.pathParam("id"));
142	                Reservation reservation = reservationService.checkOut(id);
