358	    public Collection<Reservation> findByMonth(int year, int month) {
359	        List<Reservation> result = new ArrayList<>();
360	        for (Reservation r : reservations.values()) {
361	            if (r.getCheckIn().getYear() == year && r.getCheckIn().getMonthValue() == month) {
362	                result.add(r);
363	            }
364	        }
365	        return result;
366	    }
