585	import java.math.BigDecimal;
586	import java.math.RoundingMode;
587	
588	public class PricingUtils {
589	    private static final int SCALE = 2;
590	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
591	
592	    public static BigDecimal round(BigDecimal value) {
593	        return value.setScale(SCALE, ROUNDING_MODE);
594	    }
595	
596	    public static BigDecimal multiply(BigDecimal value, int times) {
597	        BigDecimal result = value.multiply(BigDecimal.valueOf(times));
598	        return round(result);
599	    }
600	
601	    public static BigDecimal percent(BigDecimal value, int percent) {
602	        BigDecimal multiplier = BigDecimal.valueOf(percent).divide(BigDecimal.valueOf(100), SCALE + 2, ROUNDING_MODE);
603	        BigDecimal result = value.multiply(multiplier);
604	        return round(result);
605	    }
606	}
