612	public class SeasonUtils {
613	    public static boolean isHighSeason(LocalDate date) {
614	        Month month = date.getMonth();
615	        int day = date.getDayOfMonth();
616	
617	        if (month == Month.JULY) {
618	            return true;
619	        }
620	
621	        if (month == Month.DECEMBER && day >= 15) {
622	            return true;
623	        }
624	
625	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
626	            return true;
627	        }
628	
629	        return false;
630	    }
631	}

