307	    public Reservation save(Reservation reservation) {
308	        if (reservation.getId() == 0) {
309	            // Create new reservation
310	            long id = nextId++;
311	            Reservation newReservation = new Reservation(
312	                id,
313	                reservation.getRoomNumber(),
314	                reservation.getGuestName(),
315	                reservation.getGuestEmail(),
316	                reservation.getGuestCpf(),
317	                reservation.getCheckIn(),
318	                reservation.getCheckOut(),
319	                reservation.getGuests(),
320	                reservation.getRatePlan(),
321	                reservation.getNights(),
322	                reservation.getSubtotal(),
323	                reservation.getDiscount(),
324	                reservation.getTotal()
325	            );
326	            newReservation.setStatus(reservation.getStatus());
327	            newReservation.setAmountPaid(reservation.getAmountPaid());
328	            newReservation.setRefund(reservation.getRefund());
329	            reservations.put(id, newReservation);
330	            return newReservation;
331	        } else {
332	            // Update existing reservation
333	            reservations.put(reservation.getId(), reservation);
334	            return reservation;
335	        }
336	    }
