346	    public Collection<Reservation> findByRoomAndDateRange(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
347	        List<Reservation> result = new ArrayList<>();
348	        for (Reservation r : reservations.values()) {
349	            if (r.getRoomNumber() == roomNumber && r.getStatus() != ReservationStatus.CANCELLED) {
350	                if (!r.getCheckOut().isBefore(checkIn) && !r.getCheckIn().isAfter(checkOut.minusDays(1))) {
351	                    result.add(r);
352	                }
353	            }
354	        }
355	        return result;
356	    }
357	
358	    public Collection<Reservation> findByMonth(int year, int month) {
359	        List<Reservation> result = new ArrayList<>();
360	        for (Reservation r : reservations.values()) {
361	            if (r.getCheckIn().getYear() == year && r.getCheckIn().getMonthValue() == month) {
362	                result.add(r);
363	            }
364	        }
365	        return result;
366	    }
