452	public class ReservationService {
453	    private final ReservationRepository reservationRepository;
454	    private final RoomRepository roomRepository;
455	
456	    public ReservationService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
457	        this.reservationRepository = reservationRepository;
458	        this.roomRepository = roomRepository;
459	    }
460	
461	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
462	                                        LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
463	        Room room = roomRepository.findByNumber(roomNumber)
464	            .orElseThrow(() -> new RuntimeException("ROOM_NOT_FOUND"));
465	
466	        if (guests < 1) {
467	            throw new RuntimeException("INVALID_REQUEST");
468	        }
469	
470	        if (guests > room.getCapacity()) {
471	            throw new RuntimeException("CAPACITY_EXCEEDED");
472	        }
473	
474	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
475	            throw new RuntimeException("INVALID_REQUEST");
476	        }
477	
478	        // Check room availability
479	        var existingReservations = reservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
480	        if (!existingReservations.isEmpty()) {
481	            throw new RuntimeException("ROOM_UNAVAILABLE");
482	        }
483	
484	        // Calculate nights and prices
485	        int nights = (int) checkIn.until(checkOut).getDays();
486	        BigDecimal subtotal = calculateSubtotal(room, checkIn, checkOut, nights);
487	        BigDecimal discount = calculateDiscount(subtotal, ratePlan);
488	        BigDecimal total = PricingUtils.round(subtotal.subtract(discount));
489	
490	        Reservation reservation = new Reservation(0, roomNumber, guestName, guestEmail, guestCpf,
491	            checkIn, checkOut, guests, ratePlan, nights, subtotal, discount, total);
492	
493	        return reservationRepository.save(reservation);
494	    }
495	
496	    public Reservation getReservation(long id) {
497	        return reservationRepository.findById(id)
498	            .orElseThrow(() -> new RuntimeException("RESERVATION_NOT_FOUND"));
499	    }
500	
501	    public Reservation confirmReservation(long id) {
502	        Reservation reservation = getReservation(id);
503	
504	        if (reservation.getStatus() != ReservationStatus.PENDING) {
505	            throw new RuntimeException("OPERATION_NOT_ALLOWED");
506	        }
507	
508	        reservation.setStatus(ReservationStatus.CONFIRMED);
509	        reservation.setAmountPaid(reservation.getTotal());
510	        return reservationRepository.save(reservation);
511	    }
512	
513	    public Reservation checkIn(long id) {
514	        Reservation reservation = getReservation(id);
515	
516	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
517	            throw new RuntimeException("OPERATION_NOT_ALLOWED");
518	        }
519	
520	        reservation.setStatus(ReservationStatus.CHECKED_IN);
521	        return reservationRepository.save(reservation);
522	    }
523	
524	    public Reservation checkOut(long id) {
525	        Reservation reservation = getReservation(id);
526	
527	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
528	            throw new RuntimeException("OPERATION_NOT_ALLOWED");
529	        }
530	
531	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
532	        return reservationRepository.save(reservation);
533	    }
534	
535	    public Reservation cancelReservation(long id) {
536	        Reservation reservation = getReservation(id);
537	
538	        if (reservation.getStatus() != ReservationStatus.PENDING && reservation.getStatus() != ReservationStatus.CONFIRMED) {
539	            throw new RuntimeException("OPERATION_NOT_ALLOWED");
540	        }
541	
542	        reservation.setStatus(ReservationStatus.CANCELLED);
543	
544	        // Calculate refund
545	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
546	            // Refund full amount if paid
547	            if (reservation.getAmountPaid().compareTo(BigDecimal.ZERO) > 0) {
548	                reservation.setRefund(reservation.getAmountPaid());
549	            }
550	        } else {
551	            // NON_REFUNDABLE: no refund
552	            reservation.setRefund(BigDecimal.ZERO);
553	        }
554	
555	        return reservationRepository.save(reservation);
556	    }
557	
558	    private BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut, int nights) {
559	        BigDecimal total = BigDecimal.ZERO;
560	
561	        LocalDate current = checkIn;
562	        while (current.isBefore(checkOut)) {
563	            BigDecimal nightlyRate = room.getNightlyRate();
564	
565	            if (SeasonUtils.isHighSeason(current)) {
566	                nightlyRate = PricingUtils.round(nightlyRate.multiply(BigDecimal.valueOf(1.20)));
567	            }
568	
569	            total = total.add(nightlyRate);
570	            current = current.plusDays(1);
571	        }
572	
573	        return PricingUtils.round(total);
574	    }
575	
576	    private BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
577	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
578	            return PricingUtils.percent(subtotal, 15);
579	        }
580	        return BigDecimal.ZERO;
581	    }
582	}
