    40	    public String generateComprovante(Reservation reservation) {
    41	        RoomType roomType = roomRepository.findByNumber(reservation.getRoomNumber())
    42	            .orElseThrow(() -> new RuntimeException("ROOM_NOT_FOUND"))
    43	            .getType();
    44	
    45	        DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    46	        NumberFormat currencyFormat = NumberFormat.getInstance(new Locale("pt", "BR"));
    47	        currencyFormat.setMinimumFractionDigits(2);
    48	        currencyFormat.setMaximumFractionDigits(2);
    49	
    50	        StringBuilder sb = new StringBuilder();
    51	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
    52	        sb.append("Hóspede: ").append(reservation.getGuestName()).append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
    53	        sb.append("Quarto: ").append(reservation.getRoomNumber()).append(" (").append(roomType).append(")\n");
    54	        sb.append("Entrada: ").append(reservation.getCheckIn().format(dateFormatter));
    55	        sb.append(" | Saída: ").append(reservation.getCheckOut().format(dateFormatter));
    56	        sb.append(" | ");
    57	
    58	        if (reservation.getNights() == 1) {
    59	            sb.append("1 diária");
    60	        } else {
    61	            sb.append(reservation.getNights()).append(" diárias");
    62	        }
    63	
    64	        sb.append("\n");
    65	        sb.append("Diárias: R$ ").append(formatMoney(reservation.getSubtotal())).append("\n");
    66	
    67	        if (reservation.getDiscount().compareTo(java.math.BigDecimal.ZERO) > 0) {
    68	            sb.append("Desconto: R$ ").append(formatMoney(reservation.getDiscount())).append("\n");
    69	        }
    70	
    71	        sb.append("Total: R$ ").append(formatMoney(reservation.getTotal()));
    72	
    73	        return sb.toString();
    74	    }
