    76	    private String formatCpf(String cpf) {
    77	        if (cpf == null || cpf.length() != 11) {
    78	            return cpf;
    79	        }
    80	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
    81	    }
